#!/bin/sh
# Prints the Homebrew formula for a release: `homebrew-formula.sh 0.1.1 dist`,
# where `dist` holds the release's `.sha256` files. The release workflow
# writes it to Formula/martty.rb in turchenkoalex/homebrew-tap.
set -eu

version=$1
dist=$2
repo=https://github.com/turchenkoalex/martty

sha() {
  cut -d ' ' -f 1 "$dist/martty-$1.tar.gz.sha256"
}

cat <<EOF
# Generated by martty's release workflow; edits here are overwritten.
class Martty < Formula
  desc "Markdown viewer for Ghostty with images, diagrams, math and a pager"
  homepage "https://turchenkoalex.github.io/martty/"
  version "$version"
  license "Apache-2.0"

  on_macos do
    depends_on arch: :arm64

    url "$repo/releases/download/v$version/martty-aarch64-apple-darwin.tar.gz"
    sha256 "$(sha aarch64-apple-darwin)"
  end

  on_linux do
    on_intel do
      url "$repo/releases/download/v$version/martty-x86_64-unknown-linux-musl.tar.gz"
      sha256 "$(sha x86_64-unknown-linux-musl)"
    end

    on_arm do
      url "$repo/releases/download/v$version/martty-aarch64-unknown-linux-musl.tar.gz"
      sha256 "$(sha aarch64-unknown-linux-musl)"
    end
  end

  def install
    bin.install "martty"
  end

  test do
    assert_equal "martty #{version}", shell_output("#{bin}/martty --version").strip
  end
end
EOF
